<script setup lang="ts">
const niches = ref<any[]>([]); const angles = ref<any[]>([]); const nicheForm = reactive({ name: '', description: '' }); const angleForm = reactive({ nicheId: '', code: 'N1', name: '', description: '', riskLevel: 'MEDIUM' }); const message = ref(''); const alert = useAlert()
async function load() { niches.value = await $fetch('/api/niches'); angles.value = await $fetch('/api/angles'); if (!angleForm.nicheId) angleForm.nicheId = niches.value[0]?._id || '' }; onMounted(load)
async function addNiche() { await $fetch('/api/niches', { method: 'POST', body: nicheForm }); nicheForm.name = ''; nicheForm.description = ''; await load(); message.value = 'Nicho creado.' }
async function addAngle() { await $fetch('/api/angles', { method: 'POST', body: angleForm }); angleForm.name = ''; angleForm.description = ''; await load(); message.value = 'Ángulo creado.' }
async function toggle(angle: any) { await $fetch(`/api/angles/${angle._id}`, { method: 'PUT', body: { ...angle, code: angle.code || angle.id, nicheId: typeof angle.nicheId === 'object' ? angle.nicheId._id : angle.nicheId, isActive: !angle.isActive } }); await load() }
async function removeNiche(id: string) { if (await alert.confirm('Eliminar nicho', 'También se eliminarán sus ángulos y copys.')) { await $fetch(`/api/niches/${id}`, { method: 'DELETE' }); await load(); await alert.success('Nicho eliminado') } }
async function removeAngle(id: string) { if (await alert.confirm('Eliminar ángulo', 'También se eliminarán sus copys.')) { await $fetch(`/api/angles/${id}`, { method: 'DELETE' }); await load(); await alert.success('Ángulo eliminado') } }
async function editNiche(item: any) { const name = await alert.prompt('Editar nicho', item.name, 'Nombre del nicho'); if (name) { await $fetch(`/api/niches/${item._id}`, { method: 'PUT', body: { ...item, name } }); await load(); await alert.success('Nicho actualizado') } }
async function editAngle(item: any) { const code = await alert.prompt('Código del ángulo', item.code, 'Ejemplo: N1'); if (!code) return; const name = await alert.prompt('Nombre del ángulo', item.name, 'Nombre'); if (name) { await $fetch(`/api/angles/${item._id}`, { method: 'PUT', body: { ...item, code, name, riskLevel: item.riskLevel || 'MEDIUM', nicheId: item.nicheId?._id || item.nicheId } }); await load(); await alert.success('Ángulo actualizado') } }
</script>
<template><div class="mx-auto max-w-7xl px-5 py-10 lg:px-8"><div class="mb-8 flex items-end justify-between gap-4"><div><NuxtLink to="/admin" class="text-sm font-semibold text-brand">← Administración</NuxtLink><h1 class="mt-3 text-4xl font-bold">Nichos y ángulos</h1></div><p v-if="message" class="text-sm text-mint">{{ message }}</p></div><div class="grid gap-6 lg:grid-cols-2"><form class="card p-6" @submit.prevent="addNiche"><p class="eyebrow">Nuevo nicho</p><h2 class="mt-2 text-xl font-bold">Define una categoría</h2><div class="mt-5 space-y-3"><input v-model="nicheForm.name" class="input" placeholder="Ej. Diabetes" required maxlength="80"><textarea v-model="nicheForm.description" class="input" rows="3" placeholder="Descripción breve"></textarea><button class="btn-primary">Crear nicho</button></div></form><form class="card p-6" @submit.prevent="addAngle"><p class="eyebrow">Nuevo ángulo</p><h2 class="mt-2 text-xl font-bold">Añade un enfoque de venta</h2><div class="mt-5 space-y-3"><select v-model="angleForm.nicheId" class="input" required><option value="" disabled>Selecciona un nicho</option><option v-for="n in niches" :key="n._id" :value="n._id">{{ n.name }}</option></select><div class="grid grid-cols-3 gap-2"><input v-model="angleForm.code" class="input" placeholder="N1" required maxlength="20"><input v-model="angleForm.name" class="input col-span-2" placeholder="Ej. Solución natural" required maxlength="120"></div><select v-model="angleForm.riskLevel" class="input"><option value="LOW">Bajo riesgo</option><option value="MEDIUM">Riesgo medio</option><option value="HIGH">Alto riesgo</option><option value="EXTREME">Cuenta secundaria</option></select><textarea v-model="angleForm.description" class="input" rows="3" placeholder="Qué comunica este ángulo"></textarea><button class="btn-primary">Crear ángulo</button></div></form></div><section class="mt-8 space-y-3"><div v-for="niche in niches" :key="niche._id" class="card overflow-hidden"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-5"><div><h2 class="font-bold">{{ niche.name }}</h2><p class="text-sm text-slate-500">{{ niche.description || 'Sin descripción' }}</p></div><div class="flex gap-4"><button class="text-sm font-semibold text-brand" @click="editNiche(niche)">Editar</button><button class="text-sm font-semibold text-rose-500" @click="removeNiche(niche._id)">Eliminar</button></div></div><div class="divide-y divide-slate-100"><div v-for="angle in angles.filter(a => (a.nicheId?._id || a.nicheId) === niche._id)" :key="angle._id" class="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p class="font-semibold"><span class="mr-2 rounded bg-ink px-2 py-1 font-mono text-xs text-white">{{ angle.code || '?' }}</span>{{ angle.name }}</p><p class="text-sm text-slate-500">{{ angle.description || 'Sin descripción' }}</p></div><div class="flex items-center gap-3"><button class="text-sm font-semibold text-brand" @click="editAngle(angle)">Editar</button><span class="rounded-full bg-amber-100 px-2 py-1 text-xs font-bold text-amber-700">{{ angle.riskLevel || 'MEDIUM' }}</span><button class="rounded-full px-3 py-1 text-xs font-bold" :class="angle.isActive ? 'bg-mint/10 text-mint' : 'bg-slate-100 text-slate-500'" @click="toggle(angle)">{{ angle.isActive ? 'Activo' : 'Inactivo' }}</button><button class="text-sm text-rose-500" @click="removeAngle(angle._id)">Eliminar</button></div></div><p v-if="!angles.some(a => (a.nicheId?._id || a.nicheId) === niche._id)" class="p-5 text-sm text-slate-400">Sin ángulos todavía.</p></div></div><div v-if="!niches.length" class="card p-10 text-center text-slate-500">Crea tu primer nicho arriba.</div></section></div></template>
